-- DADOS INTEIRAMENTE FICTICIOS. Nao importados nem anonimizados de um ERP.

-- Execute em um banco NOVO e VAZIO selecionado no seu cliente MySQL.

-- Sem DROP, sem credenciais e sem acesso ao banco real.

SET NAMES utf8mb4;

CREATE TABLE empresa (Codigo INT PRIMARY KEY, NomeEmpresaLogin VARCHAR(100)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE produtos (Codigo INT PRIMARY KEY, Descricao VARCHAR(150), Inativo CHAR(1)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE municipios (codigo INT PRIMARY KEY, municipio VARCHAR(100)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE nfemitidas (Codigo INT PRIMARY KEY, Situacao CHAR(2)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE produtosestoque (CodEmpresa INT, CodProduto INT, EstoqueAtual DECIMAL(14,3), PRIMARY KEY (CodEmpresa, CodProduto)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE estoque (Codigo INT PRIMARY KEY, CodEmpresa INT, CodProduto INT, Data DATE, Qtde DECIMAL(14,3), TipoDoc CHAR(2)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE vendas (Codigo INT PRIMARY KEY, CodEmpresa INT, CodCliente INT, Data DATE, TotalProdutos DECIMAL(14,2), ClienteNome VARCHAR(100), ClienteEstado CHAR(2), ClienteCodMunicipio INT, ClienteApelido VARCHAR(100), DFEmitido CHAR(1), DfCodigo INT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE vendasprodutos (Codigo INT PRIMARY KEY, CodVenda INT, CodProduto INT, Quantidade DECIMAL(14,3), ValorUnitario DECIMAL(14,2), ValorTotal DECIMAL(14,2)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

